  TreeRow(){super(FileActivity.this);setWillNotDraw(false);setMinimumHeight(Ui.dp(FileActivity.this,36));label=Ui.label(FileActivity.this,"",16);label.setMaxLines(2);label.setEllipsize(android.text.TextUtils.TruncateAt.END);label.setGravity(Gravity.CENTER_VERTICAL);addView(label,new FrameLayout.LayoutParams(-1,-2,Gravity.CENTER_VERTICAL));}
