  Row(){super(FileActivity.this);setGravity(Gravity.CENTER_VERTICAL);setMinimumHeight(Ui.dp(FileActivity.this,52));setPadding(Ui.dp(FileActivity.this,6),Ui.dp(FileActivity.this,3),Ui.dp(FileActivity.this,10),Ui.dp(FileActivity.this,3));open=new LinearLayout(FileActivity.this);open.setGravity(Gravity.CENTER_VERTICAL);open.setMinimumHeight(Ui.dp(FileActivity.this,46));open.setFocusable(true);open.setClickable(true);open.setId(View.generateViewId());icon=new FileMark(FileActivity.this);open.addView(icon,new LinearLayout.LayoutParams(Ui.dp(FileActivity.this,48),Ui.dp(FileActivity.this,46)));LinearLayout texts=new LinearLayout(FileActivity.this);texts.setOrientation(1);title=Ui.label(FileActivity.this,"",18);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);detail=Ui.label(FileActivity.this,"",12);detail.setSingleLine();detail.setTextColor(Ui.muted(FileActivity.this));texts.addView(title);texts.addView(detail);open.addView(texts,new LinearLayout.LayoutParams(0,-2,1));addView(open,new LinearLayout.LayoutParams(0,-2,1));mark=new Glyph(FileActivity.this,"check");addView(mark,new LinearLayout.LayoutParams(Ui.dp(FileActivity.this,24),Ui.dp(FileActivity.this,24)));
   open.setOnFocusChangeListener((v,focused)->{if(focused&&node!=null)focusId=node.id;paint();});open.setOnKeyListener((v,key,e)->rowKey(position,key,e));open.setOnClickListener(v->{if(node==null)return;if(!picker&&!selected.isEmpty())toggle(node);else if(node.directory())navigate(node);else if(picker&&!treeMode&&!createMode){if(multiple)toggle(node);else{selected.clear();selected.add(node.id);finishSelection();}}else if(createMode)filename.setText(node.file.getName());else FileApps.open(FileActivity.this,node,false);});open.setOnLongClickListener(v->{menu(node);return true;});
  }
  void bind(int p){position=p;node=entries.get(p);title.setText(store.title(node));icon.bind(node.directory(),node.file.getName());detail.setText(node.directory()?w("Папка","Folder"):android.text.format.Formatter.formatFileSize(FileActivity.this,node.file.length())+" · "+FileCore.extension(node.file.getName()).toUpperCase(java.util.Locale.ROOT)+" · "+android.text.format.DateFormat.getDateFormat(FileActivity.this).format(node.file.lastModified()));open.setContentDescription(store.title(node)+(selected.contains(node.id)?w(", выбрано",", selected"):""));paint();}
