 private List<FileStore.Node> clipboardNodes()throws Exception {JSONArray ids=new JSONArray(getSharedPreferences("file_clipboard",0).getString("ids","[]"));ArrayList<FileStore.Node> nodes=new ArrayList<>();for(int i=0;i<ids.length();i++)nodes.add(store.node(ids.getString(i)));return nodes;}
 private void menu(FileStore.Node current){if(!allowed()){permissionMenu();return;}if(busy||current==null)return;ArrayList<ActionSheet.Item> actions=new ArrayList<>();List<FileStore.Node> nodes;try{nodes=targets(current);}catch(IOException e){error(e);return;}String object=subject(nodes);String heading=nodes.size()==1?store.title(current):w("Выбрано: ","Selected: ")+nodes.size()+" · "+object;
  if(selectable(current)&&!current.root())actions.add(item(w(selected.contains(current.id)?"Снять выделение «":"Выбрать «",selected.contains(current.id)?"Deselect «":"Select «")+store.title(current)+"»","check",()->toggle(current)));
  if(nodes.size()==1){FileStore.Node n=nodes.get(0);actions.add(item(w(n.directory()?"Открыть папку «":"Открыть файл «",n.directory()?"Open folder «":"Open file «")+store.title(n)+"»",n.directory()?"folder":"apps",()->{if(n.directory())navigate(n);else FileApps.open(this,n,false);}));}
  boolean roots=false;for(FileStore.Node n:nodes)roots|=n.root();
  if(!roots){actions.add(item(w("Копировать ","Copy ")+object+w(" в буфер"," to clipboard"),"copy",()->clipboard(nodes,false)));actions.add(item(w("Вырезать ","Cut ")+object+w(" для перемещения"," to move"),"cut",()->clipboard(nodes,true)));if(nodes.size()==1){FileStore.Node n=nodes.get(0);actions.add(item(w("Переименовать ","Rename ")+object,"rename",()->edit(w("Переименовать ","Rename ")+object,n.file.getName(),value->store.rename(n,value))));if(!n.directory())actions.add(item(w("Открыть ","Open ")+object+w(" с помощью…"," with…"),"apps",()->FileApps.open(this,n,true)));}
   actions.add(item(w("Удалить ","Delete ")+object,"delete",()->ActionSheet.show(this,w("Удалить ","Delete ")+object+"?",item(w("Удалить ","Delete ")+object,"delete",()->job(w("Удаление…","Deleting…"),()->{for(File f:FileCore.topLevel(files(nodes)))FileCore.erase(f,()->cancelled);store.purgeMissing();store.notifyChange();})))));
  }
  if(onlyFiles(nodes)){actions.add(item(w("Отправить ","Share ")+object,"share",()->FileApps.share(this,nodes)));actions.add(item(w("Отправить ","Send ")+object+w(" по Wi-Fi"," over Wi-Fi"),"share",()->FileApps.sendWifi(this,nodes)));}
  if(nodes.size()==1)actions.add(item(w("Свойства ","Properties of ")+object,"info",()->properties(current)));final String parentId=directory==null?"":directory.id,targetId=current.id;final boolean fromTree=tree.hasFocus();ActionSheet sheet=ActionSheet.showFiles(this,heading,actions.toArray(new ActionSheet.Item[0]));sheet.dialog.setOnDismissListener(d->list.post(()->{if(isFinishing()||directory==null||!directory.id.equals(parentId))return;if(fromTree){for(int i=0;i<treeItems.size();i++)if(treeItems.get(i).node.id.equals(targetId)){tree.setSelection(i);tree.requestFocus();break;}}else focusNode(targetId);}));
 }
 private ActionSheet.Item item(String text,String icon,Runnable run){return new ActionSheet.Item(text,icon,run);}
 private static List<File> files(List<FileStore.Node> nodes){ArrayList<File> result=new ArrayList<>();for(FileStore.Node n:nodes)result.add(n.file);return result;}
 private void clipboard(List<FileStore.Node> nodes,boolean cut){JSONArray a=new JSONArray();for(FileStore.Node n:nodes){if(n.root()){Ui.toast(this,"Нельзя копировать или перемещать корень хранилища","A storage root cannot be copied or moved");return;}a.put(n.id);}getSharedPreferences("file_clipboard",0).edit().putString("ids",a.toString()).putBoolean("cut",cut).apply();selected.clear();refreshRows();refreshFolderActions();Ui.toast(this,"Откройте папку назначения и нажмите «Вставить» в колонке действий","Open the destination folder and choose Paste in folder actions");}
 private void paste(){SharedPreferences prefs=getSharedPreferences("file_clipboard",0);try{JSONArray a=new JSONArray(prefs.getString("ids","[]"));if(a.length()==0){Ui.toast(this,"Буфер пуст","Clipboard empty");return;}ArrayList<FileStore.Node> nodes=new ArrayList<>();for(int i=0;i<a.length();i++)nodes.add(store.node(a.getString(i)));boolean cut=prefs.getBoolean("cut",false);FileStore.Node dest=directory;job(w("Передача файлов…","Transferring…"),()->{for(File source:FileCore.topLevel(files(nodes))){FileStore.Node n=store.identify(source);File target=FileCore.transfer(source,dest.file,cut,()->cancelled);if(cut&&!source.equals(target))store.changed(source,target);}store.notifyChange();if(cut)prefs.edit().clear().apply();});}catch(Exception e){error(e);}}
 interface Edit {void run(String value)throws Exception;}
 private void edit(String title,String initial,Edit task){EditText input=new EditText(this);input.setSingleLine();input.setText(initial);input.setSelectAllOnFocus(true);input.selectAll();new AlertDialog.Builder(this).setTitle(title).setView(input).setNegativeButton(w("Отмена","Cancel"),null).setPositiveButton(w("Сохранить","Save"),(d,which)->job(title,()->task.run(input.getText().toString()))).show();}
 interface Work {void run()throws Exception;}
 private void job(String title,Work task){if(busy)return;busy=true;cancelled=false;AlertDialog progress=new AlertDialog.Builder(this).setTitle(title).setMessage(w("Имена совпавших файлов сохраняются с новым номером. Назад — отмена оставшейся работы.","Name collisions get a new number. Back cancels remaining work.")).setNegativeButton(w("Остановить","Stop"),(d,which)->cancelled=true).create();progress.setOnCancelListener(d->cancelled=true);progress.show();worker.execute(()->{Exception failure=null;try{task.run();}catch(Exception e){failure=e;}final Exception error=failure;main.post(()->{busy=false;if(isFinishing()||isDestroyed())return;progress.dismiss();selected.clear();load();if(error!=null)new AlertDialog.Builder(this).setTitle(w("Операция не завершена","Operation incomplete")).setMessage(String.valueOf(error.getMessage())).setPositiveButton("OK",null).show();});});}
 private void properties(FileStore.Node n){new AlertDialog.Builder(this).setTitle(store.title(n)).setMessage(n.file.getAbsolutePath()+"\n"+(n.directory()?w("Папка","Folder"):FileCore.mime(n.file.getName())+"\n"+android.text.format.Formatter.formatFileSize(this,n.file.length()))+"\n"+new java.util.Date(n.file.lastModified())+"\n"+w("Чтение: ","Read: ")+n.file.canRead()+w(" · Запись: "," · Write: ")+n.file.canWrite()).setPositiveButton("OK",null).show();}
 private void finishSelection(){if(!picker||directory==null||busy)return;try{ArrayList<FileStore.Node> chosen=new ArrayList<>();if(treeMode){if(!store.treeAllowed(directory))throw new IOException("Android не разрешает выбирать этот корень");chosen.add(directory);}else if(createMode){String name=filename.getText().toString();chosen.add(store.create(directory,name,false));}else {for(String id:selected){FileStore.Node n=store.node(id);if(!n.directory()&&accepted(n))chosen.add(n);}if(chosen.isEmpty())throw new IOException("Выберите файл");if(!multiple&&chosen.size()!=1)throw new IOException("Запрошен один файл");}
   int flags=Intent.FLAG_GRANT_READ_URI_PERMISSION;if(!Intent.ACTION_GET_CONTENT.equals(action)&&!Intent.ACTION_PICK.equals(action))flags|=Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION;if(treeMode)flags|=Intent.FLAG_GRANT_PREFIX_URI_PERMISSION;if(createMode||(treeMode||Intent.ACTION_OPEN_DOCUMENT.equals(action))&&chosen.get(0).file.canWrite())flags|=Intent.FLAG_GRANT_WRITE_URI_PERMISSION;
   Uri first=treeMode?DocumentsContract.buildTreeDocumentUri(FileStore.AUTHORITY,directory.id):store.uri(chosen.get(0));Intent result=new Intent().setData(first).addFlags(flags);ClipData clip=ClipData.newRawUri(store.title(chosen.get(0)),first);for(int i=1;i<chosen.size();i++)clip.addItem(new ClipData.Item(store.uri(chosen.get(i))));result.setClipData(clip);setResult(RESULT_OK,result);finish();
  }catch(Exception e){error(e);}}
 private void error(Exception e){status.setText(w("Ошибка: ","Error: ")+String.valueOf(e.getMessage()));}
 public boolean onKeyUp(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_MENU){menu(tree.hasFocus()&&tree.getSelectedItemPosition()>=0?treeItems.get(tree.getSelectedItemPosition()).node:focusedNode());return true;}return super.onKeyUp(key,event);}
 public void onBackPressed(){if(busy){cancelled=true;return;}if(!selected.isEmpty()){boolean files=list.hasFocus();clearSelection();if(files)restoreFocus();return;}try{if(directory!=null&&!directory.root()){navigate(store.parent(directory));return;}}catch(IOException e){error(e);}setResult(RESULT_CANCELED);finish();}
